     1	'use strict';
     2	
     3	const { Store } = require('./store');
     4	const {
     5	  ValidationError,
     6	  UnknownSkuError,
     7	  UnknownOrderError,
     8	  InsufficientStockError,
     9	  OrderStateError
    10	} = require('./errors');
    11	
    12	const DEFAULT_TTL_MS = 15 * 60 * 1000;
    13	
    14	/**
    15	 * Stock reservations for checkout.
    16	 *
    17	 * Every SKU has three counters: `stock` (units on hand), `reserved` (units
    18	 * held for orders that have not been committed) and `sold`. Available stock
    19	 * is `stock - reserved` and must never go below zero.
    20	 *
    21	 * An order moves reserved -> committed, or reserved -> released. Committing
    22	 * turns its held units into sold units; releasing returns them.
    23	 *
    24	 * The service is called concurrently by every checkout worker.
    25	 */
    26	class InventoryService {
    27	  constructor({ store = new Store(), reservationTtlMs = DEFAULT_TTL_MS, now = () => Date.now() } = {}) {
    28	    this.store = store;
    29	    this.ttl = reservationTtlMs;
    30	    this.now = now;
    31	  }
    32	
    33	  /** Add units to a SKU, creating it if needed. Returns the SKU snapshot. */
    34	  async addStock(sku, qty) {
    35	    assertSku(sku);
    36	    assertQty(qty);
    37	    const item = (await this.store.get(skuKey(sku))) || { stock: 0, reserved: 0, sold: 0 };
    38	    item.stock += qty;
    39	    await this.store.set(skuKey(sku), item);
    40	    return { sku, ...item };
    41	  }
    42	
    43	  /** Units that can still be reserved. */
    44	  async available(sku) {
    45	    const item = await this.getItem(sku);
    46	    return item.stock - item.reserved;
    47	  }
    48	
    49	  /** The SKU's counters. */
    50	  async snapshot(sku) {
    51	    const item = await this.getItem(sku);
    52	    return { sku, stock: item.stock, reserved: item.reserved, sold: item.sold };
    53	  }
    54	
    55	  /**
    56	   * Hold stock for an order: all of its items, or none of them.
    57	   *
    58	   * Idempotent by orderId: checkout retries a timed-out request with the same
    59	   * orderId, and a retry must return the existing reservation rather than
    60	   * hold the stock twice.
    61	   *
    62	   * Rejects with InsufficientStockError when any item cannot be held, and
    63	   * then holds nothing.
    64	   */
    65	  async reserve(orderId, items) {
    66	    assertOrderId(orderId);
    67	    assertItems(items);
    68	    const existing = await this.store.get(orderKey(orderId));
    69	    if (existing) {
    70	      return toReservation(existing);
    71	    }
    72	    for (const { sku, qty } of items) {
    73	      const item = await this.getItem(sku);
    74	      const free = item.stock - item.reserved;
    75	      if (free < qty) {
    76	        throw new InsufficientStockError(sku, qty, free);
    77	      }
    78	      item.reserved += qty;
    79	      await this.store.set(skuKey(sku), item);
    80	    }
    81	    const order = {
    82	      orderId,
    83	      items: items.map(({ sku, qty }) => ({ sku, qty })),
    84	      status: 'reserved',
    85	      createdAt: this.now()
    86	    };
    87	    await this.store.set(orderKey(orderId), order);
    88	    return toReservation(order);
    89	  }
    90	
    91	  /**
    92	   * Turn a reservation into a sale. Idempotent: committing a committed order
    93	   * returns it unchanged. A released order cannot be committed.
    94	   */
    95	  async commit(orderId) {
    96	    const order = await this.getOrder(orderId);
    97	    if (order.status === 'committed') {
    98	      return toReservation(order);
    99	    }
   100	    if (order.status !== 'reserved') {
   101	      throw new OrderStateError(orderId, order.status, 'commit');
   102	    }
   103	    for (const { sku, qty } of order.items) {
   104	      const item = await this.getItem(sku);
   105	      item.reserved -= qty;
   106	      item.stock -= qty;
   107	      item.sold += qty;
   108	      await this.store.set(skuKey(sku), item);
   109	    }
   110	    order.status = 'committed';
   111	    await this.store.set(orderKey(orderId), order);
   112	    return toReservation(order);
   113	  }
   114	
   115	  /**
   116	   * Cancel a reservation and return its units. Idempotent: releasing a
   117	   * released order returns it unchanged. A committed order cannot be
   118	   * released; its units have been sold.
   119	   */
   120	  async release(orderId) {
   121	    const order = await this.getOrder(orderId);
   122	    if (order.status === 'released') {
   123	      return toReservation(order);
   124	    }
   125	    for (const { sku, qty } of order.items) {
   126	      const item = await this.getItem(sku);
   127	      item.reserved -= qty;
   128	      await this.store.set(skuKey(sku), item);
   129	    }
   130	    order.status = 'released';
   131	    await this.store.set(orderKey(orderId), order);
   132	    return toReservation(order);
   133	  }
   134	
   135	  /**
   136	   * Release every reservation older than the TTL that has not been committed
   137	   * or released. Returns the orderIds it released.
   138	   */
   139	  async expire() {
   140	    const cutoff = this.now() - this.ttl;
   141	    const released = [];
   142	    for (const key of await this.store.keys('order:')) {
   143	      const order = await this.store.get(key);
   144	      if (order.createdAt < cutoff) {
   145	        await this.release(order.orderId);
   146	        released.push(order.orderId);
   147	      }
   148	    }
   149	    return released;
   150	  }
   151	
   152	  async getItem(sku) {
   153	    assertSku(sku);
   154	    const item = await this.store.get(skuKey(sku));
   155	    if (!item) {
   156	      throw new UnknownSkuError(sku);
   157	    }
   158	    return item;
   159	  }
   160	
   161	  async getOrder(orderId) {
   162	    assertOrderId(orderId);
   163	    const order = await this.store.get(orderKey(orderId));
   164	    if (!order) {
   165	      throw new UnknownOrderError(orderId);
   166	    }
   167	    return order;
   168	  }
   169	}
   170	
   171	function skuKey(sku) {
   172	  return `sku:${sku}`;
   173	}
   174	
   175	function orderKey(orderId) {
   176	  return `order:${orderId}`;
   177	}
   178	
   179	function toReservation(order) {
   180	  return { orderId: order.orderId, status: order.status, items: order.items.map(({ sku, qty }) => ({ sku, qty })) };
   181	}
   182	
   183	function assertSku(sku) {
   184	  if (typeof sku !== 'string' || sku.trim() === '') {
   185	    throw new ValidationError('sku must be a non-empty string');
   186	  }
   187	}
   188	
   189	function assertOrderId(orderId) {
   190	  if (typeof orderId !== 'string' || orderId.trim() === '') {
   191	    throw new ValidationError('orderId must be a non-empty string');
   192	  }
   193	}
   194	
   195	function assertQty(qty) {
   196	  if (!Number.isInteger(qty) || qty <= 0) {
   197	    throw new ValidationError('qty must be a positive integer');
   198	  }
   199	}
   200	
   201	function assertItems(items) {
   202	  if (!Array.isArray(items) || items.length === 0) {
   203	    throw new ValidationError('items must be a non-empty array');
   204	  }
   205	  const seen = new Set();
   206	  for (const entry of items) {
   207	    if (!entry || typeof entry !== 'object') {
   208	      throw new ValidationError('each item must be an object with sku and qty');
   209	    }
   210	    assertSku(entry.sku);
   211	    assertQty(entry.qty);
   212	    if (seen.has(entry.sku)) {
   213	      throw new ValidationError(`duplicate sku in items: ${entry.sku}`);
   214	    }
   215	    seen.add(entry.sku);
   216	  }
   217	}
   218	
   219	module.exports = { InventoryService, DEFAULT_TTL_MS };
===== src/store.js
     1	'use strict';
     2	
     3	// In-memory key-value store with the latency profile of the Redis cluster
     4	// used in production: every call yields to the event loop before it reads or
     5	// writes, so concurrent callers interleave the way they do against the real
     6	// store. Values are copied on the way in and out.
     7	class Store {
     8	  constructor() {
     9	    this.data = new Map();
    10	  }
    11	
    12	  async get(key) {
    13	    await tick();
    14	    const value = this.data.get(key);
    15	    return value === undefined ? undefined : structuredClone(value);
    16	  }
    17	
    18	  async set(key, value) {
    19	    await tick();
    20	    this.data.set(key, structuredClone(value));
    21	  }
    22	
    23	  async keys(prefix) {
    24	    await tick();
    25	    return [...this.data.keys()].filter(key => key.startsWith(prefix));
    26	  }
    27	}
    28	
    29	function tick() {
    30	  return new Promise(resolve => setImmediate(resolve));
    31	}
    32	
    33	module.exports = { Store };
===== tests/inventory.test.js
     1	'use strict';
     2	
     3	const test = require('node:test');
     4	const assert = require('node:assert/strict');
     5	const {
     6	  InventoryService,
     7	  InsufficientStockError,
     8	  UnknownSkuError,
     9	  ValidationError,
    10	  OrderStateError
    11	} = require('../src');
    12	
    13	async function service(stock = { widget: 10 }) {
    14	  const svc = new InventoryService();
    15	  for (const [sku, qty] of Object.entries(stock)) {
    16	    await svc.addStock(sku, qty);
    17	  }
    18	  return svc;
    19	}
    20	
    21	test('addStock creates and tops up a sku', async () => {
    22	  const svc = new InventoryService();
    23	  assert.deepEqual(await svc.addStock('widget', 5), { sku: 'widget', stock: 5, reserved: 0, sold: 0 });
    24	  assert.deepEqual(await svc.addStock('widget', 2), { sku: 'widget', stock: 7, reserved: 0, sold: 0 });
    25	});
    26	
    27	test('reserve holds stock and commit sells it', async () => {
    28	  const svc = await service();
    29	  const reservation = await svc.reserve('o1', [{ sku: 'widget', qty: 3 }]);
    30	  assert.deepEqual(reservation, { orderId: 'o1', status: 'reserved', items: [{ sku: 'widget', qty: 3 }] });
    31	  assert.equal(await svc.available('widget'), 7);
    32	  await svc.commit('o1');
    33	  assert.deepEqual(await svc.snapshot('widget'), { sku: 'widget', stock: 7, reserved: 0, sold: 3 });
    34	});
    35	
    36	test('release returns held stock', async () => {
    37	  const svc = await service();
    38	  await svc.reserve('o1', [{ sku: 'widget', qty: 4 }]);
    39	  const released = await svc.release('o1');
    40	  assert.equal(released.status, 'released');
    41	  assert.equal(await svc.available('widget'), 10);
    42	});
    43	
    44	test('reserve is idempotent for a retried order', async () => {
    45	  const svc = await service();
    46	  await svc.reserve('o1', [{ sku: 'widget', qty: 2 }]);
    47	  await svc.reserve('o1', [{ sku: 'widget', qty: 2 }]);
    48	  assert.equal(await svc.available('widget'), 8);
    49	});
    50	
    51	test('reserve rejects when stock is short', async () => {
    52	  const svc = await service({ widget: 1 });
    53	  await assert.rejects(svc.reserve('o1', [{ sku: 'widget', qty: 2 }]), InsufficientStockError);
    54	});
    55	
    56	test('unknown skus and bad input are rejected', async () => {
    57	  const svc = await service();
    58	  await assert.rejects(svc.reserve('o1', [{ sku: 'nope', qty: 1 }]), UnknownSkuError);
    59	  await assert.rejects(svc.addStock('widget', 0), ValidationError);
    60	  await assert.rejects(svc.reserve('o1', []), ValidationError);
    61	});
    62	
    63	test('a released order cannot be committed', async () => {
    64	  const svc = await service();
    65	  await svc.reserve('o1', [{ sku: 'widget', qty: 1 }]);
    66	  await svc.release('o1');
    67	  await assert.rejects(svc.commit('o1'), OrderStateError);
    68	});
    69	
    70	test('expire releases stale reservations', async () => {
    71	  let t = 0;
    72	  const svc = new InventoryService({ now: () => t, reservationTtlMs: 1000 });
    73	  await svc.addStock('widget', 5);
    74	  await svc.reserve('o1', [{ sku: 'widget', qty: 2 }]);
    75	  t = 5000;
    76	  assert.deepEqual(await svc.expire(), ['o1']);
    77	  assert.equal(await svc.available('widget'), 5);
    78	});
