'use strict';

// Reproductions of INC-5521. Each test issues calls concurrently, the way the
// checkout workers do; none of these failures show up with sequential calls.

const { describe, test } = require('node:test');
const assert = require('node:assert/strict');
const {
  InventoryService,
  Store,
  InsufficientStockError,
  UnknownOrderError,
  OrderStateError
} = require('../src');

async function service(stock, options = {}) {
  const svc = new InventoryService(options);
  for (const [sku, qty] of Object.entries(stock)) {
    await svc.addStock(sku, qty);
  }
  return svc;
}

function settled(results) {
  return {
    fulfilled: results.filter(r => r.status === 'fulfilled').map(r => r.value),
    rejected: results.filter(r => r.status === 'rejected').map(r => r.reason)
  };
}

async function settlesWithin(promise, ms, what) {
  let timer;
  const timeout = new Promise((_, reject) => {
    timer = setTimeout(() => reject(new Error(`${what} did not settle within ${ms}ms`)), ms);
  });
  try {
    return await Promise.race([promise, timeout]);
  } finally {
    clearTimeout(timer);
  }
}

// Asserts that exactly one of two racing calls on the same order won, the
// loser was rejected as an OrderStateError, and returns the winner's index.
function oneWinner(results) {
  const { fulfilled, rejected } = settled(results);
  assert.equal(fulfilled.length, 1, 'exactly one of the racing calls should succeed');
  assert.ok(rejected[0] instanceof OrderStateError, `loser should get OrderStateError, got ${rejected[0]}`);
  return results.findIndex(r => r.status === 'fulfilled');
}

test('263 concurrent orders for 250 units confirm exactly 250 and sell 250', async () => {
  const svc = await service({ 'sneaker-limited': 250 });
  const results = await Promise.allSettled(
    Array.from({ length: 263 }, (_, i) => svc.reserve(`order-${i}`, [{ sku: 'sneaker-limited', qty: 1 }]))
  );
  const { fulfilled, rejected } = settled(results);
  assert.equal(fulfilled.length, 250);
  assert.equal(rejected.length, 13);
  for (const err of rejected) {
    assert.ok(err instanceof InsufficientStockError);
    assert.equal(err.available, 0);
  }
  assert.deepEqual(await svc.snapshot('sneaker-limited'), { sku: 'sneaker-limited', stock: 250, reserved: 250, sold: 0 });

  await Promise.all(fulfilled.map(({ orderId }) => svc.commit(orderId)));
  assert.deepEqual(await svc.snapshot('sneaker-limited'), { sku: 'sneaker-limited', stock: 0, reserved: 0, sold: 250 });
});

test('a retried reserve racing the original holds the units once', async () => {
  const svc = await service({ widget: 10 });
  const [first, retry] = await Promise.all([
    svc.reserve('o1', [{ sku: 'widget', qty: 3 }]),
    svc.reserve('o1', [{ sku: 'widget', qty: 3 }])
  ]);
  assert.deepEqual(retry, first);
  assert.equal(await svc.available('widget'), 7);
  await svc.release('o1');
  assert.equal(await svc.available('widget'), 10);
});

test('when bundles race for the last unit, the losing order holds none of its items', async () => {
  const svc = await service({ shirt: 10, cap: 1 });
  const results = await Promise.allSettled(
    ['o1', 'o2', 'o3'].map(id => svc.reserve(id, [{ sku: 'shirt', qty: 1 }, { sku: 'cap', qty: 1 }]))
  );
  const { fulfilled, rejected } = settled(results);
  assert.equal(fulfilled.length, 1);
  assert.ok(rejected.every(err => err instanceof InsufficientStockError));
  assert.deepEqual(await svc.snapshot('shirt'), { sku: 'shirt', stock: 10, reserved: 1, sold: 0 });
  assert.deepEqual(await svc.snapshot('cap'), { sku: 'cap', stock: 1, reserved: 1, sold: 0 });
});

test('concurrent commits of one order count the sale once', async () => {
  const svc = await service({ widget: 10 });
  await svc.reserve('o1', [{ sku: 'widget', qty: 2 }]);
  const results = await Promise.all([svc.commit('o1'), svc.commit('o1'), svc.commit('o1')]);
  for (const reservation of results) {
    assert.equal(reservation.status, 'committed');
  }
  assert.deepEqual(await svc.snapshot('widget'), { sku: 'widget', stock: 8, reserved: 0, sold: 2 });
});

test('concurrent releases of one order return its units once', async () => {
  const svc = await service({ widget: 10 });
  await svc.reserve('o1', [{ sku: 'widget', qty: 2 }]);
  await svc.reserve('o2', [{ sku: 'widget', qty: 3 }]);
  await Promise.all([svc.release('o1'), svc.release('o1'), svc.release('o1')]);
  assert.deepEqual(await svc.snapshot('widget'), { sku: 'widget', stock: 10, reserved: 3, sold: 0 });
});

test('a commit racing a release of the same order applies only one of them', async () => {
  const svc = await service({ widget: 10 });
  await svc.reserve('o1', [{ sku: 'widget', qty: 2 }]);
  const winner = oneWinner(await Promise.allSettled([svc.commit('o1'), svc.release('o1')]));
  const expected = winner === 0 ? { stock: 8, reserved: 0, sold: 2 } : { stock: 10, reserved: 0, sold: 0 };
  assert.deepEqual(await svc.snapshot('widget'), { sku: 'widget', ...expected });
});

test('expire racing a commit never releases the committed order', async () => {
  let t = 0;
  const svc = await service({ widget: 10 }, { now: () => t, reservationTtlMs: 1000 });
  await svc.reserve('o1', [{ sku: 'widget', qty: 2 }]);
  t = 5000;
  const [commit, expire] = await Promise.allSettled([svc.commit('o1'), svc.expire()]);
  assert.equal(expire.status, 'fulfilled', `expire must not fail: ${expire.reason}`);
  if (commit.status === 'fulfilled') {
    assert.deepEqual(expire.value, []);
    assert.deepEqual(await svc.snapshot('widget'), { sku: 'widget', stock: 8, reserved: 0, sold: 2 });
  } else {
    assert.ok(commit.reason instanceof OrderStateError);
    assert.deepEqual(expire.value, ['o1']);
    assert.deepEqual(await svc.snapshot('widget'), { sku: 'widget', stock: 10, reserved: 0, sold: 0 });
  }
});

test('overlapping expire runs release each stale order once', async () => {
  let t = 0;
  const svc = await service({ widget: 10 }, { now: () => t, reservationTtlMs: 1000 });
  const ids = ['o1', 'o2', 'o3', 'o4', 'o5'];
  for (const id of ids) {
    await svc.reserve(id, [{ sku: 'widget', qty: 1 }]);
  }
  t = 5000;
  const [first, second] = await Promise.all([svc.expire(), svc.expire()]);
  assert.deepEqual([...first, ...second].sort(), ids);
  assert.deepEqual(await svc.snapshot('widget'), { sku: 'widget', stock: 10, reserved: 0, sold: 0 });
});

test('concurrent addStock calls keep every unit', async () => {
  const svc = new InventoryService();
  await Promise.all(Array.from({ length: 50 }, () => svc.addStock('widget', 2)));
  assert.deepEqual(await svc.snapshot('widget'), { sku: 'widget', stock: 100, reserved: 0, sold: 0 });
});

test('bundles that list shared SKUs in opposite order do not deadlock', async () => {
  const svc = await service({ a: 100, b: 100 });
  const bundles = Array.from({ length: 40 }, (_, i) =>
    svc.reserve(`o${i}`, i % 2 ? [{ sku: 'a', qty: 1 }, { sku: 'b', qty: 1 }] : [{ sku: 'b', qty: 1 }, { sku: 'a', qty: 1 }])
  );
  await settlesWithin(Promise.all(bundles), 2000, 'opposite-order bundles');
  const settle = Array.from({ length: 40 }, (_, i) => (i % 2 ? svc.commit(`o${i}`) : svc.release(`o${i}`)));
  await settlesWithin(Promise.all(settle), 2000, 'commits and releases');
  for (const sku of ['a', 'b']) {
    assert.deepEqual(await svc.snapshot(sku), { sku, stock: 80, reserved: 0, sold: 20 });
  }
});

test('calls that share no SKU and no order do not wait for each other', async () => {
  // Reads of one SKU stall until the test opens the gate, standing in for a
  // slow store round trip on a hot key.
  class GatedStore extends Store {
    constructor(gatedKey) {
      super();
      this.gatedKey = gatedKey;
      this.closed = false;
      this.gate = new Promise(resolve => { this.open = resolve; });
    }

    async get(key) {
      if (this.closed && key === this.gatedKey) {
        await this.gate;
      }
      return super.get(key);
    }
  }

  const store = new GatedStore('sku:slow');
  const svc = await service({ slow: 5, fast: 5 }, { store });
  store.closed = true;
  let slowDone = false;
  const slow = svc.reserve('o-slow', [{ sku: 'slow', qty: 1 }]).then(result => {
    slowDone = true;
    return result;
  });

  await settlesWithin(
    (async () => {
      await svc.reserve('o-fast', [{ sku: 'fast', qty: 2 }]);
      await svc.commit('o-fast');
      await svc.reserve('o-fast-2', [{ sku: 'fast', qty: 1 }]);
      await svc.release('o-fast-2');
      await svc.addStock('fast', 1);
    })(),
    1000,
    'calls on an unrelated SKU while another SKU is stalled'
  );
  assert.equal(slowDone, false, 'the stalled reserve should still be waiting on its store read');
  assert.deepEqual(await svc.snapshot('fast'), { sku: 'fast', stock: 4, reserved: 0, sold: 2 });

  store.open();
  assert.equal((await slow).status, 'reserved');
  assert.equal(await svc.available('slow'), 4);
});

test('services built over the same store exclude each other', async () => {
  const store = new Store();
  const a = new InventoryService({ store });
  const b = new InventoryService({ store });
  await a.addStock('widget', 10);
  const results = await Promise.allSettled(
    Array.from({ length: 20 }, (_, i) => (i % 2 ? a : b).reserve(`o${i}`, [{ sku: 'widget', qty: 1 }]))
  );
  assert.equal(settled(results).fulfilled.length, 10);
  assert.deepEqual(await b.snapshot('widget'), { sku: 'widget', stock: 10, reserved: 10, sold: 0 });
});

// Same three methods as Store, but each call waits 0-3 event-loop turns so the
// interleavings differ from Store's, and values are not copied, so the service
// cannot rely on mutating what it read.
class JitterStore {
  constructor(random) {
    this.data = new Map();
    this.random = random;
  }

  async get(key) {
    await this.delay();
    return this.data.get(key);
  }

  async set(key, value) {
    await this.delay();
    this.data.set(key, value);
  }

  async keys(prefix) {
    await this.delay();
    return [...this.data.keys()].filter(key => key.startsWith(prefix));
  }

  async delay() {
    for (let turns = Math.floor(this.random() * 4); turns > 0; turns--) {
      await new Promise(resolve => setImmediate(resolve));
    }
  }
}

// mulberry32: a small seeded PRNG so every run replays the same traffic.
function seededRandom(seed) {
  let state = seed;
  return () => {
    state = (state + 0x6d2b79f5) | 0;
    let t = Math.imul(state ^ (state >>> 15), 1 | state);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

async function checkoutTraffic(store, random) {
  const pick = list => list[Math.floor(random() * list.length)];
  const between = (low, high) => low + Math.floor(random() * (high - low + 1));
  const skus = ['a', 'b', 'café'];
