// Same three methods as Store, but each call waits 0-3 event-loop turns so the
// interleavings differ from Store's, and values are not copied, so the service
// cannot rely on mutating what it read.
class JitterStore {
  constructor(random) {
    this.data = new Map();
    this.random = random;
  }

  async get(key) {
    await this.delay();
    return this.data.get(key);
  }

  async set(key, value) {
    await this.delay();
    this.data.set(key, value);
  }

  async keys(prefix) {
    await this.delay();
    return [...this.data.keys()].filter(key => key.startsWith(prefix));
  }

  async delay() {
    for (let turns = Math.floor(this.random() * 4); turns > 0; turns--) {
      await new Promise(resolve => setImmediate(resolve));
    }
  }
}

// mulberry32: a small seeded PRNG so every run replays the same traffic.
function seededRandom(seed) {
  let state = seed;
  return () => {
    state = (state + 0x6d2b79f5) | 0;
    let t = Math.imul(state ^ (state >>> 15), 1 | state);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

async function checkoutTraffic(store, random) {
  const pick = list => list[Math.floor(random() * list.length)];
  const between = (low, high) => low + Math.floor(random() * (high - low + 1));
  const skus = ['a', 'b', 'café'];
  const orderIds = Array.from({ length: 40 }, (_, i) => `order-${i}`);
  // Every now() call advances the clock, so orders created early in the run
  // are stale by the time later expire() calls look at them.
  let clock = 0;
  const svc = new InventoryService({ store, now: () => clock++, reservationTtlMs: 20 });
  const added = {};
  for (const sku of skus) {
    await svc.addStock(sku, 15);
    added[sku] = 15;
  }

  const reservations = [];
  const calls = [];
  const counts = { commit: 0, release: 0, expired: 0 };
  for (let i = 0; i < 400; i++) {
    const roll = random();
    if (roll < 0.4) {
      const orderId = pick(orderIds);
      const lines = [...new Set([pick(skus), pick(skus)])].map(sku => ({ sku, qty: between(1, 4) }));
      calls.push(svc.reserve(orderId, lines).then(r => reservations.push(r)));
    } else if (roll < 0.6) {
      calls.push(svc.commit(pick(orderIds)).then(() => counts.commit++));
    } else if (roll < 0.8) {
      calls.push(svc.release(pick(orderIds)).then(() => counts.release++));
    } else if (roll < 0.9) {
      const sku = pick(skus);
      const qty = between(1, 3);
      calls.push(svc.addStock(sku, qty).then(() => { added[sku] += qty; }));
    } else {
      calls.push(svc.expire().then(ids => { counts.expired += ids.length; }));
    }
  }

  for (const result of await Promise.allSettled(calls)) {
    if (result.status === 'rejected') {
      const err = result.reason;
      const expected = err instanceof InsufficientStockError || err instanceof UnknownOrderError || err instanceof OrderStateError;
      assert.ok(expected, `unexpected rejection: ${err && err.stack}`);
    }
  }
  assert.ok(counts.commit > 0 && counts.release > 0 && counts.expired > 0, `traffic should exercise every path: ${JSON.stringify(counts)}`);

  const orders = new Map();
  for (const key of await store.keys('order:')) {
    const order = await store.get(key);
    orders.set(order.orderId, order);
  }
  for (const reservation of reservations) {
    assert.deepEqual(reservation.items, orders.get(reservation.orderId).items, `retries of ${reservation.orderId} must return the original items`);
  }
  for (const sku of skus) {
    let reserved = 0;
    let sold = 0;
    for (const order of orders.values()) {
      for (const line of order.items.filter(l => l.sku === sku)) {
        if (order.status === 'reserved') reserved += line.qty;
        if (order.status === 'committed') sold += line.qty;
      }
    }
    assert.deepEqual(await svc.snapshot(sku), { sku, stock: added[sku] - sold, reserved, sold }, `counters for ${sku}`);
  }
}

describe('randomised checkout traffic keeps every counter equal to its orders', () => {
  for (const seed of [1, 2, 3]) {
    test(`default store, seed ${seed}`, () => checkoutTraffic(new Store(), seededRandom(seed)));
    test(`jittery store that does not copy values, seed ${seed}`, () => {
      const random = seededRandom(seed);
      return checkoutTraffic(new JitterStore(random), random);
    });
  }
});

