'use strict';

const { test } = require('node:test');
const assert = require('node:assert/strict');
const { KeyedLock } = require('../src/keyed-lock');

const tick = () => new Promise(resolve => setImmediate(resolve));

test('callers on one key run one at a time, in the order they asked', async () => {
  const locks = new KeyedLock();
  const events = [];
  const worker = name => locks.run(['k'], async () => {
    events.push(`${name} in`);
    await tick();
    events.push(`${name} out`);
  });
  await Promise.all([worker('a'), worker('b'), worker('c')]);
  assert.deepEqual(events, ['a in', 'a out', 'b in', 'b out', 'c in', 'c out']);
});

test('a held key does not block callers on other keys', async () => {
  const locks = new KeyedLock();
  let freeA;
  const holdingA = locks.run(['a'], () => new Promise(resolve => { freeA = resolve; }));
  assert.equal(await locks.run(['b', 'c'], async () => 'ran'), 'ran');
  freeA();
  await holdingA;
});

test('run frees its keys when the callback throws', async () => {
  const locks = new KeyedLock();
  await assert.rejects(locks.run(['k'], async () => { throw new Error('boom'); }), /boom/);
  assert.equal(await locks.run(['k'], async () => 'next caller got the key'), 'next caller got the key');
});

test('a key listed twice in one call is taken once', async () => {
  const locks = new KeyedLock();
  assert.equal(await locks.run(['k', 'k'], async () => 'ran'), 'ran');
});

test('keys are forgotten once nobody holds or waits for them', async () => {
  const locks = new KeyedLock();
  let free;
  const holding = locks.run(['a', 'b'], () => new Promise(resolve => { free = resolve; }));
  const waiting = locks.run(['b'], async () => {});
  await tick();
  assert.equal(locks.size, 2);
  free();
  await Promise.all([holding, waiting]);
  assert.equal(locks.size, 0);
});

