288	async function checkoutTraffic(store, random) {
289	  const pick = list => list[Math.floor(random() * list.length)];
290	  const between = (low, high) => low + Math.floor(random() * (high - low + 1));
291	  const skus = ['a', 'b', 'café'];
292	  const orderIds = Array.from({ length: 60 }, (_, i) => `order-${i}`);
293	  // Every now() call advances the clock, so orders created early in the run
294	  // are stale by the time later expire() calls look at them.
295	  let clock = 0;
296	  const svc = new InventoryService({ store, now: () => clock++, reservationTtlMs: 3 });
297	  const added = {};
298	  for (const sku of skus) {
299	    await svc.addStock(sku, 15);
300	    added[sku] = 15;
301	  }
302	
303	  const reservations = [];
304	  const calls = [];
305	  const counts = { commit: 0, release: 0, expired: 0 };
306	  // Launches are spread over the first 60 event-loop turns so that commits,
307	  // releases and expiries find orders to act on.
308	  for (let i = 0; i < 400; i++) {
309	    const roll = random();
310	    let call;
311	    if (roll < 0.45) {
312	      const orderId = pick(orderIds);
313	      const lines = [...new Set([pick(skus), pick(skus)])].map(sku => ({ sku, qty: between(1, 4) }));
314	      call = () => svc.reserve(orderId, lines).then(r => reservations.push(r));
315	    } else if (roll < 0.6) {
316	      const orderId = pick(orderIds);
317	      call = () => svc.commit(orderId).then(() => counts.commit++);
318	    } else if (roll < 0.75) {
319	      const orderId = pick(orderIds);
320	      call = () => svc.release(orderId).then(() => counts.release++);
321	    } else if (roll < 0.85) {
322	      const sku = pick(skus);
323	      const qty = between(1, 3);
324	      call = () => svc.addStock(sku, qty).then(() => { added[sku] += qty; });
325	    } else {
326	      call = () => svc.expire().then(ids => { counts.expired += ids.length; });
327	    }
328	    calls.push(turns(between(0, 60)).then(call));
329	  }
330	
331	  for (const result of await Promise.allSettled(calls)) {
332	    if (result.status === 'rejected') {
333	      const err = result.reason;
334	      const expected = err instanceof InsufficientStockError || err instanceof UnknownOrderError || err instanceof OrderStateError;
335	      assert.ok(expected, `unexpected rejection: ${err && err.stack}`);
336	    }
337	  }
338	  assert.ok(counts.commit > 0 && counts.release > 0 && counts.expired > 0, `traffic should exercise every path: ${JSON.stringify(counts)}`);
339	
340	  const orders = new Map();
341	  for (const key of await store.keys('order:')) {
342	    const order = await store.get(key);
343	    orders.set(order.orderId, order);
344	  }
345	  for (const reservation of reservations) {
346	    assert.deepEqual(reservation.items, orders.get(reservation.orderId).items, `retries of ${reservation.orderId} must return the original items`);
347	  }
348	  for (const sku of skus) {
349	    let reserved = 0;
350	    let sold = 0;
351	    for (const order of orders.values()) {
352	      for (const line of order.items.filter(l => l.sku === sku)) {
353	        if (order.status === 'reserved') reserved += line.qty;
354	        if (order.status === 'committed') sold += line.qty;
355	      }
356	    }
357	    assert.deepEqual(await svc.snapshot(sku), { sku, stock: added[sku] - sold, reserved, sold }, `counters for ${sku}`);
358	  }
359	}
