// Two store client objects over one backend (e.g. two Redis clients in one process).
const R = process.argv[2];
const { InventoryService } = require(R + '/src');
const backend = new Map();
const tick = () => new Promise(r => setImmediate(r));
class Client {
  async get(k) { await tick(); const v = backend.get(k); return v === undefined ? undefined : structuredClone(v); }
  async set(k, v) { await tick(); backend.set(k, structuredClone(v)); }
  async keys(p) { await tick(); return [...backend.keys()].filter(k => k.startsWith(p)); }
}
(async () => {
  const a = new InventoryService({ store: new Client() });
  const b = new InventoryService({ store: new Client() });
  await a.addStock('sneaker', 5);
  const results = await Promise.allSettled(Array.from({ length: 10 }, (_, i) => (i % 2 ? a : b).reserve('o' + i, [{ sku: 'sneaker', qty: 1 }])));
  console.log('fulfilled', results.filter(r => r.status === 'fulfilled').length, 'snapshot', await a.snapshot('sneaker'));
})();
EOF
