   266	// Same three methods as Store, but each call waits 0-3 event-loop turns so the
   267	// interleavings differ from Store's, and values are not copied, so the service
   268	// cannot rely on mutating what it read.
   269	class JitterStore {
   270	  constructor(random) {
   271	    this.data = new Map();
   272	    this.random = random;
   273	  }
   274	
   275	  async get(key) {
   276	    await this.delay();
   277	    return this.data.get(key);
   278	  }
   279	
   280	  async set(key, value) {
   281	    await this.delay();
   282	    this.data.set(key, value);
   283	  }
   284	
   285	  async keys(prefix) {
   286	    await this.delay();
   287	    return [...this.data.keys()].filter(key => key.startsWith(prefix));
   288	  }
   289	
   290	  async delay() {
   291	    for (let turns = Math.floor(this.random() * 4); turns > 0; turns--) {
   292	      await new Promise(resolve => setImmediate(resolve));
   293	    }
   294	  }
   295	}
   296	
   297	// mulberry32: a small seeded PRNG so every run replays the same traffic.
   298	function seededRandom(seed) {
   299	  let state = seed;
   300	  return () => {
   301	    state = (state + 0x6d2b79f5) | 0;
   302	    let t = Math.imul(state ^ (state >>> 15), 1 | state);
   303	    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
   304	    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
   305	  };
   306	}
