   308	async function checkoutTraffic(store, random) {
   309	  const pick = list => list[Math.floor(random() * list.length)];
   310	  const between = (low, high) => low + Math.floor(random() * (high - low + 1));
   311	  const skus = ['a', 'b', 'café'];
   312	  const orderIds = Array.from({ length: 60 }, (_, i) => `order-${i}`);
   313	  // Every now() call advances the clock, so orders created early in the run
   314	  // are stale by the time later expire() calls look at them.
   315	  let clock = 0;
   316	  const svc = new InventoryService({ store, now: () => clock++, reservationTtlMs: 3 });
   317	  const added = {};
   318	  for (const sku of skus) {
   319	    await svc.addStock(sku, 15);
   320	    added[sku] = 15;
   321	  }
   322	
   323	  const reservations = [];
   324	  const calls = [];
   325	  const counts = { commit: 0, release: 0, expired: 0 };
   326	  // Launches are spread over the first 60 event-loop turns so that commits,
   327	  // releases and expiries find orders to act on.
   328	  for (let i = 0; i < 400; i++) {
   329	    const roll = random();
   330	    let call;
   331	    if (roll < 0.45) {
   332	      const orderId = pick(orderIds);
   333	      const lines = [...new Set([pick(skus), pick(skus)])].map(sku => ({ sku, qty: between(1, 4) }));
   334	      call = () => svc.reserve(orderId, lines).then(r => reservations.push(r));
   335	    } else if (roll < 0.6) {
   336	      const orderId = pick(orderIds);
   337	      call = () => svc.commit(orderId).then(() => counts.commit++);
   338	    } else if (roll < 0.75) {
   339	      const orderId = pick(orderIds);
   340	      call = () => svc.release(orderId).then(() => counts.release++);
   341	    } else if (roll < 0.85) {
   342	      const sku = pick(skus);
   343	      const qty = between(1, 3);
   344	      call = () => svc.addStock(sku, qty).then(() => { added[sku] += qty; });
   345	    } else {
   346	      call = () => svc.expire().then(ids => { counts.expired += ids.length; });
   347	    }
   348	    calls.push(turns(between(0, 60)).then(call));
   349	  }
   350	
   351	  for (const result of await Promise.allSettled(calls)) {
   352	    if (result.status === 'rejected') {
   353	      const err = result.reason;
   354	      const expected = err instanceof InsufficientStockError || err instanceof UnknownOrderError || err instanceof OrderStateError;
   355	      assert.ok(expected, `unexpected rejection: ${err && err.stack}`);
   356	    }
   357	  }
   358	  assert.ok(counts.commit > 0 && counts.release > 0 && counts.expired > 0, `traffic should exercise every path: ${JSON.stringify(counts)}`);
   359	
   360	  const orders = new Map();
   361	  for (const key of await store.keys('order:')) {
   362	    const order = await store.get(key);
   363	    orders.set(order.orderId, order);
   364	  }
   365	  for (const reservation of reservations) {
   366	    assert.deepEqual(reservation.items, orders.get(reservation.orderId).items, `retries of ${reservation.orderId} must return the original items`);
   367	  }
   368	  for (const sku of skus) {
   369	    let reserved = 0;
   370	    let sold = 0;
   371	    for (const order of orders.values()) {
   372	      for (const line of order.items.filter(l => l.sku === sku)) {
   373	        if (order.status === 'reserved') reserved += line.qty;
   374	        if (order.status === 'committed') sold += line.qty;
   375	      }
   376	    }
   377	    assert.deepEqual(await svc.snapshot(sku), { sku, stock: added[sku] - sold, reserved, sold }, `counters for ${sku}`);
   378	  }
   379	}
   380	
   381	describe('randomised checkout traffic keeps every counter equal to its orders', () => {
   382	  for (const seed of [1, 2, 3]) {
   383	    test(`default store, seed ${seed}`, () => checkoutTraffic(new Store(), seededRandom(seed)));
   384	    test(`jittery store that does not copy values, seed ${seed}`, () => {
   385	      const random = seededRandom(seed);
   386	      return checkoutTraffic(new JitterStore(random), random);
   387	    });
   388	  }
   389	});

