'use strict';

/**
 * In-process mutual exclusion per string key. Callers on different keys never
 * wait for each other; callers on the same key run one at a time, in the
 * order they reached it. A key is tracked only while someone holds or waits for
 * it, so memory follows the number of busy keys, not the size of the catalog.
 *
 * Locks are not re-entrant: a caller that already holds a key and asks for it
 * again waits for itself forever.
 */
class KeyedLock {
  constructor() {
    this.tails = new Map();
  }

  /** Number of keys currently held or waited for. */
  get size() {
    return this.tails.size;
  }

  /** Wait until `key` is free, take it, and return a function that frees it. */
  async acquire(key) {
    const previous = this.tails.get(key) || Promise.resolve();
    let free;
    const held = new Promise(resolve => { free = resolve; });
    const tail = previous.then(() => held);
    this.tails.set(key, tail);
    await previous;
    return () => {
      if (this.tails.get(key) === tail) {
        this.tails.delete(key);
      }
      free();
    };
  }

  /**
   * Run `fn` while holding every key in `keys`, and free them when it settles.
   * Keys are taken in sorted order, so callers whose key sets overlap cannot
   * deadlock however they list them.
   */
  async run(keys, fn) {
    const frees = [];
    try {
      for (const key of [...new Set(keys)].sort()) {
        // Taken one at a time: sorted acquisition is what rules out deadlock.
        frees.push(await this.acquire(key));
      }
      return await fn();
    } finally {
      for (const free of frees.reverse()) {
        free();
      }
    }
  }
}

module.exports = { KeyedLock };

