'use strict';

const { test } = require('node:test');
const assert = require('node:assert/strict');
const { KeyedLock } = require('../src/keyed-lock');

const tick = () => new Promise(resolve => setImmediate(resolve));

test('callers on one key run one at a time, in the order they called', async () => {
  const locks = new KeyedLock();
  const events = [];
  const worker = name => locks.run('k', async () => {
    events.push(`${name} in`);
    await tick();
    events.push(`${name} out`);
  });
  await Promise.all([worker('a'), worker('b'), worker('c')]);
  assert.deepEqual(events, ['a in', 'a out', 'b in', 'b out', 'c in', 'c out']);
});

test('a held key does not block callers on other keys', async () => {
  const locks = new KeyedLock();
  let freeA;
  const holdingA = locks.run('a', () => new Promise(resolve => { freeA = resolve; }));
  assert.equal(await locks.run('b', async () => 'ran'), 'ran');
  freeA();
  await holdingA;
});

test('run frees its key when the callback throws', async () => {
  const locks = new KeyedLock();
  await assert.rejects(locks.run('k', async () => { throw new Error('boom'); }), /boom/);
  assert.equal(await locks.run('k', async () => 'next caller got the key'), 'next caller got the key');
});

test('a caller arriving after a handover queues behind the caller that got the key', async () => {
  const locks = new KeyedLock();
  let active = 0;
  let overlapped = false;
  const worker = async () => {
    active++;
    overlapped = overlapped || active > 1;
    await tick();
    active--;
  };
  const first = locks.run('k', worker);
  const second = locks.run('k', worker);
  await first;
  await Promise.all([second, locks.run('k', worker)]);
  assert.equal(overlapped, false);
});

test('keys are forgotten once nobody holds or waits for them', async () => {
  const locks = new KeyedLock();
  let free;
  const holding = locks.run('a', () => new Promise(resolve => { free = resolve; }));
  const waiting = locks.run('a', async () => {});
  await locks.run('b', async () => {});
  assert.equal(locks.size, 1);
  free();
  await Promise.all([holding, waiting]);
  assert.equal(locks.size, 0);
});

