  3	/**
  4	 * In-process mutual exclusion per string key. Callers on different keys never
  5	 * wait for each other; callers on the same key run one at a time, in the
  6	 * order they called. A key is tracked only while someone holds or waits for
  7	 * it, so memory follows the number of busy keys, not the size of the catalog.
  8	 *
  9	 * Locks are not re-entrant: a caller that already holds a key and asks for it
 10	 * again waits for itself forever.
 11	 */
 12	class KeyedLock {
 13	  constructor() {
 14	    this.tails = new Map();
 15	  }
 16	
 17	  /** Number of keys currently held or waited for. */
 18	  get size() {
 19	    return this.tails.size;
 20	  }
 21	
 22	  /** Run `fn` while holding `key`, and free the key when `fn` settles. */
 23	  async run(key, fn) {
 24	    const previous = this.tails.get(key) || Promise.resolve();
 25	    let free;
 26	    const held = new Promise(resolve => { free = resolve; });
 27	    const tail = previous.then(() => held);
 28	    this.tails.set(key, tail);
 29	    try {
 30	      await previous;
 31	      return await fn();
 32	    } finally {
 33	      if (this.tails.get(key) === tail) {
 34	        this.tails.delete(key);
 35	      }
 36	      free();
 37	    }
 38	  }
 39	}
