 25	function settled(results) {
 26	  return {
 27	    fulfilled: results.filter(r => r.status === 'fulfilled').map(r => r.value),
 28	    rejected: results.filter(r => r.status === 'rejected').map(r => r.reason)
 29	  };
 30	}
 31	
 32	function turns(count) {
 33	  let wait = Promise.resolve();
 34	  for (let i = 0; i < count; i++) {
 35	    wait = wait.then(() => new Promise(resolve => setImmediate(resolve)));
 36	  }
 37	  return wait;
 38	}
