 40	// Starts call i after i event-loop turns, so each call lands at a different
 41	// point of the calls already in flight. Calls that all start on the same turn
 42	// hit identical interleavings and can hide a double apply behind a lost update.
 43	function staggered(count, call) {
 44	  return Promise.allSettled(Array.from({ length: count }, (_, i) => turns(i).then(call)));
 45	}
