 47	async function settlesWithin(promise, ms, what) {
 48	  let timer;
 49	  const timeout = new Promise((_, reject) => {
 50	    timer = setTimeout(() => reject(new Error(`${what} did not settle within ${ms}ms`)), ms);
 51	  });
 52	  try {
 53	    return await Promise.race([promise, timeout]);
 54	  } finally {
 55	    clearTimeout(timer);
 56	  }
 57	}
