362	  const reservations = [];
363	  const calls = [];
364	  const counts = { commit: 0, release: 0, expired: 0 };
365	  // Launches are spread over the first 60 event-loop turns so that commits,
366	  // releases and expiries find orders to act on.
367	  for (let i = 0; i < 400; i++) {
