const { InventoryService, Store, UnknownOrderError } = require('../src');
class Flaky extends Store {
  constructor() { super(); this.fail = () => false; }
  async set(key, value) { if (this.fail(key, value)) throw new Error('store down: ' + key); return super.set(key, value); }
}
async function mk() { const store = new Flaky(); const svc = new InventoryService({ store }); await svc.addStock('a', 5); await svc.addStock('b', 5); return { store, svc }; }
(async () => {
  // P3: order write fails -> holds returned?
  { const { store, svc } = await mk(); store.fail = k => k === 'order:o1';
    const e = await svc.reserve('o1', [{ sku: 'a', qty: 2 }, { sku: 'b', qty: 1 }]).catch(e => e);
    console.log('P3 order write fails:', e.message, JSON.stringify([await svc.snapshot('a'), await svc.snapshot('b')])); }
  // P2: SKU write on b fails, and rollback write on a also fails (store down for all writes after first)
  { const { store, svc } = await mk(); let writes = 0; store.fail = () => ++writes > 1;
    const e = await svc.reserve('o1', [{ sku: 'a', qty: 2 }, { sku: 'b', qty: 1 }]).catch(e => e);
    store.fail = () => false;
    const e2 = await svc.release('o1').catch(e => e.constructor.name);
    console.log('P2 rollback fails: error seen =', e.message, '| a =', JSON.stringify(await svc.snapshot('a')), '| release(o1) ->', e2); }
  // L6: commit fails part-way, retry
  { const { store, svc } = await mk(); await svc.reserve('o1', [{ sku: 'a', qty: 2 }, { sku: 'b', qty: 1 }]);
    store.fail = k => k === 'sku:b';
    const e = await svc.commit('o1').catch(e => e.message);
    store.fail = () => false;
    await svc.commit('o1');
    console.log('L6 commit partial then retry:', e, JSON.stringify([await svc.snapshot('a'), await svc.snapshot('b')])); }
})();
EOF
